--
-- Name: anonymize_user(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.anonymize_user(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_anon_suffix TEXT := substr(md5(p_user_id::TEXT), 1, 8);
BEGIN
    -- Nahrazení PII hash hodnotami (pseudonymizace)
    UPDATE identity.users SET
        email           = 'anonymized_' || v_anon_suffix || '@deleted.invalid',
        phone           = NULL,
        name            = 'Anonymized User ' || v_anon_suffix,
        password_hash   = 'ANONYMIZED',
        deleted_at      = COALESCE(deleted_at, NOW()),
        anonymized_at   = NOW()
    WHERE id = p_user_id
      AND anonymized_at IS NULL;

    -- Revokace všech aktivních refresh tokenů
    UPDATE identity.refresh_tokens SET
        revoked_at = NOW()
    WHERE user_id = p_user_id
      AND revoked_at IS NULL;

    -- Deaktivace MFA konfigurací
    UPDATE identity.mfa_configs SET
        is_active = FALSE
    WHERE user_id = p_user_id;
END;
$$;


--
-- Name: FUNCTION anonymize_user(p_user_id uuid); Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON FUNCTION identity.anonymize_user(p_user_id uuid) IS 'GDPR right to erasure: pseudonymizuje PII uživatele, revokuje tokeny a deaktivuje MFA. Auditní záznamy a transakční data zůstávají pro EET compliance.';


--
-- Name: move_password_to_secrets(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.move_password_to_secrets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
BEGIN
  INSERT INTO identity.user_secrets (user_id, password_hash, updated_at)
  VALUES (NEW.id, NEW.password_hash, now())
  ON CONFLICT (user_id) DO UPDATE
    SET password_hash = EXCLUDED.password_hash, updated_at = now();
  -- vynuluj v users (tento UPDATE má password_hash NULL → WHEN podmínka false → bez rekurze)
  UPDATE identity.users SET password_hash = NULL WHERE id = NEW.id;
  RETURN NULL;
END;
$$;


