--
-- Name: sync_user_name(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.sync_user_name() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Při INSERT/UPDATE syncujeme name z first_name + last_name (pokud existují).
  -- Pokud aplikace dodá jen `name` (legacy), naopak split a fill first/last.
  IF NEW.first_name IS NOT NULL OR NEW.last_name IS NOT NULL THEN
    NEW.name := TRIM(COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''));
    IF NEW.name = '' THEN NEW.name := NULL; END IF;
  ELSIF NEW.name IS NOT NULL AND NEW.first_name IS NULL AND NEW.last_name IS NULL THEN
    -- Legacy code-path: aplikace dodá jen `name` → rozdělíme
    NEW.first_name := split_part(NEW.name, ' ', 1);
    NEW.last_name := NULLIF(regexp_replace(NEW.name, '^[^\s]+\s*', ''), '');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_otp_rate_limit(text); Type: FUNCTION; Schema: marketing; Owner: -
--

CREATE FUNCTION marketing.check_otp_rate_limit(p_phone text) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE recent_count integer;
BEGIN
  SELECT COUNT(*) INTO recent_count FROM marketing.otp_codes
   WHERE phone_e164 = p_phone AND created_at > NOW() - INTERVAL '10 minutes';
  RETURN recent_count < 3;
END;
$$;


--
-- Name: FUNCTION check_otp_rate_limit(p_phone text); Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON FUNCTION marketing.check_otp_rate_limit(p_phone text) IS 'Returns true pokud phone má < 3 OTP requests v posledních 10 min';


--
-- Name: cleanup_expired_spotify_oauth(); Type: FUNCTION; Schema: marketing; Owner: -
--

CREATE FUNCTION marketing.cleanup_expired_spotify_oauth() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE deleted_count integer;
BEGIN
  DELETE FROM marketing.spotify_oauth_pending WHERE expires_at < NOW()
  RETURNING 1 INTO deleted_count;
  RETURN COALESCE(deleted_count, 0);
END;
$$;


--
-- Name: set_default_currency_for_country(); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.set_default_currency_for_country() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.country = 'SR' AND OLD.country IS DISTINCT FROM 'SR'
     AND NEW.primary_currency = OLD.primary_currency THEN
    NEW.primary_currency := 'EUR';
  END IF;
  RETURN NEW;
END;
$$;


