--
-- Name: audit_trigger_func(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_trigger_func() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
    v_record_id TEXT;
    v_old_values JSONB;
    v_new_values JSONB;
    v_actor_id   UUID;
    v_actor_type TEXT;
    v_ip_address INET;
BEGIN
    -- Načtení kontextu z aplikační session proměnné
    BEGIN
        v_actor_id   := current_setting('app.current_user_id', TRUE)::UUID;
    EXCEPTION WHEN OTHERS THEN
        v_actor_id   := NULL;
    END;

    v_actor_type := COALESCE(current_setting('app.role', TRUE), 'system');

    BEGIN
        v_ip_address := current_setting('app.client_ip', TRUE)::INET;
    EXCEPTION WHEN OTHERS THEN
        v_ip_address := NULL;
    END;

    IF TG_OP = 'INSERT' THEN
        v_record_id  := NEW.id::TEXT;
        v_old_values := NULL;
        v_new_values := to_jsonb(NEW);
    ELSIF TG_OP = 'UPDATE' THEN
        v_record_id  := NEW.id::TEXT;
        v_old_values := to_jsonb(OLD);
        v_new_values := to_jsonb(NEW);
    ELSIF TG_OP = 'DELETE' THEN
        v_record_id  := OLD.id::TEXT;
        v_old_values := to_jsonb(OLD);
        v_new_values := NULL;
    END IF;

    INSERT INTO audit.audit_log (
        schema_name,
        table_name,
        record_id,
        action,
        actor_id,
        actor_type,
        old_values,
        new_values,
        ip_address
    ) VALUES (
        TG_TABLE_SCHEMA,
        TG_TABLE_NAME,
        v_record_id,
        TG_OP,
        v_actor_id,
        v_actor_type,
        v_old_values,
        v_new_values,
        v_ip_address
    );

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION audit_trigger_func(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.audit_trigger_func() IS 'Generická AFTER trigger funkce pro zápis do audit.audit_log. Čte kontext z app.current_user_id, app.role, app.client_ip session proměnných.';


