--
-- Name: enforce_listing_expiry_24h(); Type: FUNCTION; Schema: resale; Owner: -
--

CREATE FUNCTION resale.enforce_listing_expiry_24h() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_event_start TIMESTAMPTZ;
BEGIN
  SELECT e.date_start INTO v_event_start
  FROM tickets.tickets t
  JOIN catalog.ticket_types tt ON tt.id = t.ticket_type_id
  JOIN catalog.events e ON e.id = tt.event_id
  WHERE t.id = NEW.ticket_id;

  IF v_event_start IS NULL THEN
    RAISE EXCEPTION 'ticket % not found or has no event', NEW.ticket_id;
  END IF;

  IF NEW.expires_at IS NULL OR NEW.expires_at > (v_event_start - INTERVAL '24 hours') THEN
    NEW.expires_at := v_event_start - INTERVAL '24 hours';
  END IF;

  IF NEW.expires_at <= NOW() THEN
    RAISE EXCEPTION 'event % too soon — resale expiry already passed', NEW.ticket_id
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION enforce_listing_expiry_24h(); Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON FUNCTION resale.enforce_listing_expiry_24h() IS 'Feature #46: clamps resale listing expiry to event_start - 24h and rejects listings created within the final 24h.';


