--
-- Name: accessible_seats; Type: TABLE; Schema: accessibility; Owner: -
--

CREATE TABLE accessibility.accessible_seats (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    seat_id text NOT NULL,
    seat_section text,
    accessibility_type text NOT NULL,
    is_available boolean DEFAULT true NOT NULL,
    reserved_until timestamp with time zone,
    notes text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT accessible_seats_accessibility_type_check CHECK ((accessibility_type = ANY (ARRAY['wheelchair_accessible'::text, 'wheelchair_companion_space'::text, 'accessible_toilet_nearby'::text, 'hearing_loop'::text, 'accessible_entrance'::text])))
);


--
-- Name: accommodations; Type: TABLE; Schema: accessibility; Owner: -
--

CREATE TABLE accessibility.accommodations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    accommodation_type text NOT NULL,
    additional_info text,
    verified boolean DEFAULT false NOT NULL,
    verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT accommodations_accommodation_type_check CHECK ((accommodation_type = ANY (ARRAY['wheelchair_access'::text, 'blind_person_guide'::text, 'deaf_support'::text, 'mobility_assistance'::text, 'service_animal_space'::text, 'accessible_toilet'::text, 'hearing_loop'::text, 'audio_description'::text])))
);


--
-- Name: companion_pairs; Type: TABLE; Schema: accessibility; Owner: -
--

CREATE TABLE accessibility.companion_pairs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    primary_ticket_id uuid NOT NULL,
    companion_ticket_id uuid NOT NULL,
    relationship_type text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT companion_pairs_relationship_type_check CHECK ((relationship_type = ANY (ARRAY['assistant'::text, 'carer'::text, 'support_person'::text, 'guide'::text]))),
    CONSTRAINT no_self_pairing CHECK ((primary_ticket_id <> companion_ticket_id))
);


