    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    requester_name text NOT NULL,
    requester_email text NOT NULL,
    organization text NOT NULL,
    media_type text NOT NULL,
    requested_zones text[] DEFAULT '{}'::text[] NOT NULL,
    purpose text,
    portfolio_url text,
    status text DEFAULT 'pending'::text NOT NULL,
    reviewed_by uuid,
    review_notes text,
    approved_zones text[] DEFAULT '{}'::text[] NOT NULL,
    qr_code_payload text,
    qr_issued_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT accreditation_requests_media_type_check CHECK ((media_type = ANY (ARRAY['press'::text, 'photo'::text, 'tv'::text, 'radio'::text, 'online'::text, 'podcast'::text, 'other'::text]))),
    CONSTRAINT accreditation_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'rejected'::text, 'revoked'::text])))
);


--
-- Name: accreditation_scans; Type: TABLE; Schema: accreditation; Owner: -
--

CREATE TABLE accreditation.accreditation_scans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    accreditation_id uuid NOT NULL,
    zone_id text NOT NULL,
    gate_id text,
    scanned_at timestamp with time zone DEFAULT now() NOT NULL,
    result text NOT NULL,
    deny_reason text,
    CONSTRAINT accreditation_scans_result_check CHECK ((result = ANY (ARRAY['allowed'::text, 'denied'::text])))
);


--
-- Name: dynamic_creative_templates; Type: TABLE; Schema: ads; Owner: -
--

CREATE TABLE ads.dynamic_creative_templates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    promoter_id uuid NOT NULL,
