    cta_text text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT dynamic_creative_templates_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text])))
);


--
-- Name: affiliates; Type: TABLE; Schema: affiliate; Owner: -
--

CREATE TABLE affiliate.affiliates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    commission_rate_bps integer DEFAULT 500 NOT NULL,
    wallet_balance integer DEFAULT 0 NOT NULL,
    payout_threshold integer DEFAULT 100000 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT affiliates_commission_rate_bps_check CHECK (((commission_rate_bps >= 0) AND (commission_rate_bps <= 5000))),
    CONSTRAINT affiliates_payout_threshold_check CHECK ((payout_threshold > 0)),
    CONSTRAINT affiliates_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'closed'::text]))),
    CONSTRAINT affiliates_wallet_balance_check CHECK ((wallet_balance >= 0))
);


--
-- Name: clicks; Type: TABLE; Schema: affiliate; Owner: -
--

CREATE TABLE affiliate.clicks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    link_id uuid NOT NULL,
    session_id text,
    referrer text,
    ip_hash text,
    user_agent text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE clicks; Type: COMMENT; Schema: affiliate; Owner: -
--

COMMENT ON TABLE affiliate.clicks IS 'Raw kliknutí na affiliate link. Fire-and-forget INSERT mimo transakci.
   Pro statistiky stačí click_count counter na affiliate.links.';


--
-- Name: COLUMN clicks.ip_hash; Type: COMMENT; Schema: affiliate; Owner: -
--

COMMENT ON COLUMN affiliate.clicks.ip_hash IS 'SHA-256 hash IP adresy pro fraud detection. Raw IP se neukládá (GDPR).';


--
-- Name: conversions; Type: TABLE; Schema: affiliate; Owner: -
--

CREATE TABLE affiliate.conversions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    link_id uuid NOT NULL,
    affiliate_id uuid NOT NULL,
    order_id uuid NOT NULL,
    order_amount integer NOT NULL,
    commission integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT conversions_commission_check CHECK ((commission >= 0)),
    CONSTRAINT conversions_order_amount_check CHECK ((order_amount >= 0)),
    CONSTRAINT conversions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'paid'::text, 'reversed'::text])))
);


--
-- Name: links; Type: TABLE; Schema: affiliate; Owner: -
--

CREATE TABLE affiliate.links (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    affiliate_id uuid NOT NULL,
    event_id uuid,
    code character varying(20) NOT NULL,
    click_count integer DEFAULT 0 NOT NULL,
    conversion_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT links_click_count_check CHECK ((click_count >= 0)),
    CONSTRAINT links_conversion_count_check CHECK ((conversion_count >= 0))
);


--
-- Name: COLUMN links.code; Type: COMMENT; Schema: affiliate; Owner: -
--

COMMENT ON COLUMN affiliate.links.code IS 'Base62 kód (8 znaků) generovaný přes crypto.getRandomValues. Používá se v URL /r/{code}.';


--
-- Name: payouts; Type: TABLE; Schema: affiliate; Owner: -
--

CREATE TABLE affiliate.payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    affiliate_id uuid NOT NULL,
    amount integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    bank_reference text,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payouts_amount_check CHECK ((amount > 0)),
    CONSTRAINT payouts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'paid'::text, 'failed'::text])))
);


--
-- Name: generated_ad_copies; Type: TABLE; Schema: ai_ads; Owner: -
--

CREATE TABLE ai_ads.generated_ad_copies (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    platform text DEFAULT 'facebook'::text NOT NULL,
    headlines text[] NOT NULL,
    body_copy text[] NOT NULL,
    call_to_actions text[] NOT NULL,
    generated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT generated_ad_copies_platform_check CHECK ((platform = ANY (ARRAY['facebook'::text, 'instagram'::text, 'email'::text])))
);


--
-- Name: ambassadors; Type: TABLE; Schema: ambassador; Owner: -
--

CREATE TABLE ambassador.ambassadors (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    name character varying(200) NOT NULL,
    tier text DEFAULT 'bronze'::text NOT NULL,
    commission_rate_bps integer DEFAULT 1000 NOT NULL,
    wallet_balance integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ambassadors_commission_rate_bps_check CHECK (((commission_rate_bps >= 0) AND (commission_rate_bps <= 3000))),
    CONSTRAINT ambassadors_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'deactivated'::text]))),
    CONSTRAINT ambassadors_tier_check CHECK ((tier = ANY (ARRAY['bronze'::text, 'silver'::text, 'gold'::text]))),
    CONSTRAINT ambassadors_wallet_balance_check CHECK ((wallet_balance >= 0))
);


--
-- Name: COLUMN ambassadors.commission_rate_bps; Type: COMMENT; Schema: ambassador; Owner: -
--

COMMENT ON COLUMN ambassador.ambassadors.commission_rate_bps IS 'Provizní sazba v basis points. Max 3000 = 30 %. Výpočet: Math.floor((amount * bps) / 10_000).';


--
-- Name: code_usages; Type: TABLE; Schema: ambassador; Owner: -
--

CREATE TABLE ambassador.code_usages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code_id uuid NOT NULL,
    order_id uuid NOT NULL,
    order_amount integer NOT NULL,
    commission integer NOT NULL,
    used_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT code_usages_commission_check CHECK ((commission >= 0)),
    CONSTRAINT code_usages_order_amount_check CHECK ((order_amount >= 0))
);


--
-- Name: TABLE code_usages; Type: COMMENT; Schema: ambassador; Owner: -
--

COMMENT ON TABLE ambassador.code_usages IS 'Immutable log použití ambasadorských kódů. ON CONFLICT (order_id) DO NOTHING pro idempotenci.';


--
-- Name: codes; Type: TABLE; Schema: ambassador; Owner: -
--

CREATE TABLE ambassador.codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ambassador_id uuid NOT NULL,
    code character varying(20) NOT NULL,
    max_uses integer,
    used_count integer DEFAULT 0 NOT NULL,
    discount_bps integer DEFAULT 0 NOT NULL,
    valid_until timestamp with time zone,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT codes_discount_bps_check CHECK (((discount_bps >= 0) AND (discount_bps <= 10000))),
    CONSTRAINT codes_max_uses_check CHECK (((max_uses IS NULL) OR (max_uses > 0))),
    CONSTRAINT codes_used_count_check CHECK ((used_count >= 0))
);


--
-- Name: COLUMN codes.code; Type: COMMENT; Schema: ambassador; Owner: -
--

COMMENT ON COLUMN ambassador.codes.code IS 'Promo kód generovaný z vlastního charstetu (bez O,0,I,1 pro snížení záměn).';


--
-- Name: COLUMN codes.discount_bps; Type: COMMENT; Schema: ambassador; Owner: -
--

COMMENT ON COLUMN ambassador.codes.discount_bps IS 'Sleva pro kupujícího použitím kódu (basis points). 0 = žádná sleva, pouze tracking.';


--
-- Name: payouts; Type: TABLE; Schema: ambassador; Owner: -
--

CREATE TABLE ambassador.payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ambassador_id uuid NOT NULL,
    amount integer NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    bank_reference text,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payouts_amount_check CHECK ((amount > 0)),
    CONSTRAINT payouts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'paid'::text, 'failed'::text])))
);


--
-- Name: audience_geo; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.audience_geo (
    event_id uuid NOT NULL,
    country_code text NOT NULL,
    postal_code text NOT NULL,
    buyer_count integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: demand_forecasts; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.demand_forecasts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    ticket_type_id uuid,
    computed_at timestamp with time zone DEFAULT now() NOT NULL,
    days_to_event integer NOT NULL,
    sold_pct numeric(5,2) NOT NULL,
    velocity_per_day numeric(10,2) NOT NULL,
    projected_final_pct numeric(5,2),
    recommended_price_halire bigint,
    price_change_reason text,
    auto_applied boolean DEFAULT false NOT NULL
);


--
-- Name: event_sales_snapshots; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.event_sales_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    event_id uuid NOT NULL,
    tickets_sold integer DEFAULT 0 NOT NULL,
    revenue_total bigint DEFAULT 0 NOT NULL,
    unique_buyers integer DEFAULT 0 NOT NULL
);


--
-- Name: funnel_events; Type: TABLE; Schema: analytics; Owner: -
--

CREATE TABLE analytics.funnel_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id text NOT NULL,
    user_id uuid,
    event_id uuid NOT NULL,
    step text NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT funnel_events_step_check CHECK ((step = ANY (ARRAY['event_view'::text, 'ticket_selection'::text, 'seat_selection'::text, 'checkout_start'::text, 'payment_info'::text, 'order_complete'::text])))
);


--
-- Name: TABLE funnel_events; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON TABLE analytics.funnel_events IS 'Raw checkout funnel events. Fire-and-forget INSERT (trackStep je void — neblokuje checkout).
   Anonymní tracking — user_id může být NULL pro GDPR compliance.
   Záznamy se po 90 dnech archivují (GDPR data minimisation).';


--
-- Name: COLUMN funnel_events.step; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON COLUMN analytics.funnel_events.step IS 'Krok funnelu: event_view → ticket_selection → seat_selection →
   checkout_start → payment_info → order_complete.
   Drop-off rate = 1 - (count(next_step) / count(current_step)).';


--
-- Name: COLUMN funnel_events.metadata; Type: COMMENT; Schema: analytics; Owner: -
--

COMMENT ON COLUMN analytics.funnel_events.metadata IS 'Volitelný kontext kroku (ticketTypeId, quantity, errorCode, device, ...).
   Neukládáme PII — pouze technické identifikátory.';


--
-- Name: users; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    email text NOT NULL,
    phone text,
    name text,
    password_hash text,
    email_verified_at timestamp with time zone,
    phone_verified_at timestamp with time zone,
    gdpr_consent_at timestamp with time zone NOT NULL,
    deleted_at timestamp with time zone,
    anonymized_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    is_platform_admin boolean DEFAULT false NOT NULL,
    stripe_customer_id text,
    first_name text,
    last_name text,
    birth_year integer,
    gender text,
    country_code text,
    city text,
    postal_code text,
    fan_id_verified boolean DEFAULT false NOT NULL,
    fan_id_verified_at timestamp with time zone,
    CONSTRAINT users_gender_check CHECK ((gender = ANY (ARRAY[NULL::text, 'male'::text, 'female'::text, 'other'::text, 'prefer_not_to_say'::text])))
);


--
-- Name: COLUMN users.email; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.email IS 'Primární kontaktní e-mail; po anonymizaci (GDPR right to erasure) nahrazen hash hodnotou.';


--
-- Name: COLUMN users.phone; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.phone IS 'Volitelné telefonní číslo; po anonymizaci set na NULL.';


--
-- Name: COLUMN users.name; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.name IS 'Auto-derived z first_name + last_name přes trigger trg_sync_user_name. NEPIŠ přímo — používej first_name/last_name.';


--
-- Name: COLUMN users.password_hash; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.password_hash IS 'Argon2id hash hesla; nikdy plaintext.';


--
-- Name: COLUMN users.gdpr_consent_at; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.gdpr_consent_at IS 'Timestamp udělení GDPR souhlasu; povinný při registraci.';


--
-- Name: COLUMN users.deleted_at; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.deleted_at IS 'Soft delete — záznam zůstává pro referenční integritu a EET; PII odstraněno přes anonymized_at.';


--
-- Name: COLUMN users.anonymized_at; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.anonymized_at IS 'Kdy proběhla GDPR anonymizace (pseudonymizace PII polí).';


--
-- Name: COLUMN users.stripe_customer_id; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.stripe_customer_id IS 'Persistent Stripe Customer ID — vytvořen při prvním checkoutu s payment plan; používá se pro charging installments.';


--
-- Name: COLUMN users.first_name; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.first_name IS 'Source of truth pro křestní jméno. Sync trigger auto-updates name = first_name || last_name.';


--
-- Name: COLUMN users.last_name; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.last_name IS 'Source of truth pro příjmení.';


--
-- Name: orders; Type: TABLE; Schema: orders; Owner: -
--

CREATE TABLE orders.orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    total_amount integer NOT NULL,
    currency character(3) DEFAULT 'CZK'::bpchar NOT NULL,
    locale character varying(10) DEFAULT 'cs'::character varying NOT NULL,
    gopay_payment_id text,
    gopay_order_id text,
    idempotency_key uuid DEFAULT gen_random_uuid() NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    event_id uuid,
    payment_provider text DEFAULT 'gopay'::text,
    stripe_payment_intent_id text,
    stripe_customer_id text,
    discount_halire integer DEFAULT 0 NOT NULL,
    promo_code_id uuid,
    requires_age_verification boolean DEFAULT false NOT NULL,
    is_gift boolean DEFAULT false NOT NULL,
    gift_recipient_email text,
    gift_recipient_name text,
    gift_message text,
    gift_redeem_token text,
    gift_redeemed_at timestamp with time zone,
    gift_redeemed_user_id uuid,
    affiliate_id uuid,
    affiliate_commission_minor bigint,
    fraud_score integer,
    fraud_signals jsonb,
    fraud_decision text,
    abandoned_email_sent_at timestamp with time zone,
    recovered_via_email boolean DEFAULT false NOT NULL,
    holder_names text[],
    entry_slot_id uuid,
    variable_symbol text,
    stripe_payment_method_id text,
    tan_validated_at timestamp with time zone,
    cancelled_by_buyer_at timestamp with time zone,
    cancellation_reason text,
    cancellation_refund_status text,
    delivery_method text DEFAULT 'digital'::text,
    will_call_picked_up_at timestamp with time zone,
    will_call_picked_up_by_user_id uuid,
    qr_campaign_id uuid,
    group_invitation_id uuid,
    comp_type character varying(20),
    comp_notes text,
    resale_listing_id uuid,
    carbon_offset_halire integer DEFAULT 0 NOT NULL,
    withdrawal_rights_shown boolean DEFAULT false NOT NULL,
    billing_postal_code text,
    billing_country_code text,
    is_box_office boolean DEFAULT false NOT NULL,
    box_office_session_id uuid,
    postal_fee_halire integer DEFAULT 0 NOT NULL,
    loyalty_points_earned bigint,
    loyalty_points_redeemed bigint,
    loyalty_discount_halire bigint,
    placed_by_agent_id uuid,
    order_source text DEFAULT 'web'::text NOT NULL,
    phone_payment_link text,
    phone_payment_expires_at timestamp with time zone,
    service_fee_minor integer DEFAULT 0 NOT NULL,
    buyer_vat_number text,
    buyer_company_name text,
    is_reverse_charge boolean DEFAULT false NOT NULL,
    CONSTRAINT orders_cancellation_refund_status_check CHECK ((cancellation_refund_status = ANY (ARRAY[NULL::text, 'no_refund'::text, 'pending'::text, 'approved'::text, 'completed'::text, 'rejected'::text]))),
    CONSTRAINT orders_comp_type_check CHECK (((comp_type)::text = ANY ((ARRAY['press'::character varying, 'vip'::character varying, 'artist'::character varying, 'sponsor'::character varying, 'staff'::character varying, 'other'::character varying])::text[]))),
    CONSTRAINT orders_delivery_method_check CHECK ((delivery_method = ANY (ARRAY['digital'::text, 'postal'::text]))),
    CONSTRAINT orders_discount_halire_check CHECK ((discount_halire >= 0)),
    CONSTRAINT orders_fraud_decision_check CHECK ((fraud_decision = ANY (ARRAY['allow'::text, 'review'::text, 'block'::text, NULL::text]))),
    CONSTRAINT orders_payment_provider_check CHECK ((payment_provider = ANY (ARRAY['mock'::text, 'gopay'::text, 'comgate'::text, 'stripe'::text, 'wero'::text, 'przelewy24'::text, 'bank_transfer'::text, 'twisto'::text, 'skippay'::text, 'pluxee'::text, 'sodexo'::text, 'benefit_plus'::text, 'edenred'::text, 'multisport'::text, 'voucher'::text, 'charity'::text, 'free'::text, 'crypto'::text, 'comp'::text]))),
    CONSTRAINT orders_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'paid'::text, 'paid_partial'::text, 'cancelled'::text, 'refunded'::text, 'expired'::text, 'chargeback'::text]))),
    CONSTRAINT orders_total_amount_check CHECK ((total_amount >= 0))
);


--
-- Name: COLUMN orders.user_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.user_id IS 'UUID uživatele z identity.users; cross-schema reference — bez FK.';


--
-- Name: COLUMN orders.status; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.status IS 'Stav objednávky: pending → paid → (refunded | expired | chargeback) nebo pending → cancelled.
   chargeback: kupující zpochybnil platbu u banky — platba stornována bankou.';


--
-- Name: COLUMN orders.currency; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.currency IS 'ISO 4217 kód měny (CZK, EUR, …).';


--
-- Name: COLUMN orders.locale; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.locale IS 'Locale kupujícího při nákupu (cs, en, de, …). Používá se pro generování emailů a PDF vstupenek ve správném jazyce.';


--
-- Name: COLUMN orders.gopay_payment_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.gopay_payment_id IS 'Interní ID platby v GoPay systému.';


--
-- Name: COLUMN orders.gopay_order_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.gopay_order_id IS 'ID objednávky v GoPay systému pro párování webhooků.';


--
-- Name: COLUMN orders.idempotency_key; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.idempotency_key IS 'UUID pro idempotentní zpracování; zabraňuje duplicitním objednávkám při síťových chybách.';


--
-- Name: COLUMN orders.expires_at; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.expires_at IS 'Deadline pro dokončení platby; po vypršení přechází objednávka do stavu expired.';


--
-- Name: COLUMN orders.event_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.event_id IS 'UUID akce z catalog.events; cross-schema reference bez FK. Slouží pro payout settlement per event.';


--
-- Name: COLUMN orders.payment_provider; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.payment_provider IS 'Platební provider použitý pro tuto objednávku. Výchozí gopay pro zpětnou kompatibilitu.';


--
-- Name: COLUMN orders.stripe_payment_intent_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.stripe_payment_intent_id IS 'Stripe PaymentIntent ID (pi_...). Unikátní per objednávka. NULL pro ne-Stripe platby.';


--
-- Name: COLUMN orders.stripe_customer_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.stripe_customer_id IS 'Stripe Customer ID (cus_...). Volitelné — ukládá se pro returning customers.';


--
-- Name: COLUMN orders.discount_halire; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.discount_halire IS 'Výše slevy z promo kódu v haléřích. total_amount = subtotal - discount_halire.';


--
-- Name: COLUMN orders.promo_code_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.promo_code_id IS 'UUID použitého promo kódu z marketing.promo_codes. NULL = žádný kód. Cross-schema, bez FK.';


--
-- Name: COLUMN orders.holder_names; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.orders.holder_names IS 'Volitelný seznam jmen pro personalizované vstupenky. Length = quantity. Issuer přiřadí postupně.';


--
-- Name: COLUMN orders.entry_slot_id; Type: COMMENT; Schema: orders; Owner: -
--

