--
-- Name: vw_event_demographics; Type: VIEW; Schema: analytics; Owner: -
--

CREATE VIEW analytics.vw_event_demographics AS
 SELECT o.event_id,
    count(*) AS buyer_count,
    count(*) FILTER (WHERE ((u.birth_year >= ((EXTRACT(year FROM now()))::integer - 24)) AND (u.birth_year <= ((EXTRACT(year FROM now()))::integer - 18)))) AS age_18_24,
    count(*) FILTER (WHERE ((u.birth_year >= ((EXTRACT(year FROM now()))::integer - 34)) AND (u.birth_year <= ((EXTRACT(year FROM now()))::integer - 25)))) AS age_25_34,
    count(*) FILTER (WHERE ((u.birth_year >= ((EXTRACT(year FROM now()))::integer - 44)) AND (u.birth_year <= ((EXTRACT(year FROM now()))::integer - 35)))) AS age_35_44,
    count(*) FILTER (WHERE ((u.birth_year >= ((EXTRACT(year FROM now()))::integer - 54)) AND (u.birth_year <= ((EXTRACT(year FROM now()))::integer - 45)))) AS age_45_54,
    count(*) FILTER (WHERE ((u.birth_year IS NOT NULL) AND (u.birth_year < ((EXTRACT(year FROM now()))::integer - 54)))) AS age_55_plus,
    count(*) FILTER (WHERE (u.gender = 'male'::text)) AS gender_male,
    count(*) FILTER (WHERE (u.gender = 'female'::text)) AS gender_female,
    count(*) FILTER (WHERE (u.gender = 'other'::text)) AS gender_other,
    jsonb_object_agg(COALESCE(u.country_code, 'unknown'::text), c.cnt) FILTER (WHERE ((u.country_code IS NOT NULL) OR true)) AS by_country
   FROM ((orders.orders o
     JOIN identity.users u ON ((u.id = o.user_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS cnt
           FROM (orders.orders o2
             JOIN identity.users u2 ON ((u2.id = o2.user_id)))
          WHERE ((o2.event_id = o.event_id) AND (u2.country_code = u.country_code))) c ON (true))
  WHERE (o.status = 'paid'::text)
  GROUP BY o.event_id;


