    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT blacklist_entries_scope_check CHECK ((scope = ANY (ARRAY['platform'::text, 'promoter'::text]))),
    CONSTRAINT blacklist_entries_status_check CHECK ((status = ANY (ARRAY['active'::text, 'appealing'::text, 'lifted'::text]))),
    CONSTRAINT chk_blacklist_lifted_consistency CHECK ((((status = 'lifted'::text) AND (lifted_at IS NOT NULL) AND (lifted_by IS NOT NULL)) OR (status <> 'lifted'::text))),
    CONSTRAINT chk_blacklist_promoter_scope CHECK ((((scope = 'platform'::text) AND (promoter_id IS NULL)) OR ((scope = 'promoter'::text) AND (promoter_id IS NOT NULL))))
);


--
-- Name: TABLE blacklist_entries; Type: COMMENT; Schema: blacklist; Owner: -
--

COMMENT ON TABLE blacklist.blacklist_entries IS 'Záznamy banů uživatelů. Platform scope = ban napříč celou platformou.
   Promoter scope = ban pouze pro konkrétního promotéra.
   checkBan vrací NULL i pro neexistující záznamy (anti-enumeration).';


