--
-- Name: mv_event_inventory_status; Type: MATERIALIZED VIEW; Schema: catalog; Owner: -
--

CREATE MATERIALIZED VIEW catalog.mv_event_inventory_status AS
 SELECT e.id AS event_id,
    e.promoter_id,
    e.status AS event_status,
    count(tt.id) AS ticket_type_count,
    sum(tt.total_qty) AS total_capacity,
    sum(tt.remaining_qty) AS total_remaining,
    sum((tt.total_qty - tt.remaining_qty)) AS total_sold,
    min(tt.base_price) AS min_price,
    max(tt.base_price) AS max_price,
        CASE
            WHEN (sum(tt.remaining_qty) = 0) THEN 'sold_out'::text
            WHEN (((sum(tt.remaining_qty))::numeric / (NULLIF(sum(tt.total_qty), 0))::numeric) < 0.10) THEN 'almost_sold_out'::text
            WHEN (((sum(tt.remaining_qty))::numeric / (NULLIF(sum(tt.total_qty), 0))::numeric) < 0.25) THEN 'selling_fast'::text
            ELSE 'available'::text
        END AS availability_status,
    now() AS snapshot_at
   FROM (catalog.events e
     LEFT JOIN catalog.ticket_types tt ON (((tt.event_id = e.id) AND (tt.visibility = 'public'::text))))
  WHERE ((e.status = 'published'::text) AND (e.date_start >= now()))
  GROUP BY e.id, e.promoter_id, e.status
  WITH NO DATA;


--
-- Name: MATERIALIZED VIEW mv_event_inventory_status; Type: COMMENT; Schema: catalog; Owner: -
--

COMMENT ON MATERIALIZED VIEW catalog.mv_event_inventory_status IS 'Inventory Status API source. REFRESH MATERIALIZED VIEW CONCURRENTLY á 1 minuta přes cron.';


