--
-- Name: vw_price_elasticity; Type: VIEW; Schema: catalog; Owner: -
--

CREATE VIEW catalog.vw_price_elasticity AS
 WITH price_changes AS (
         SELECT h.ticket_type_id,
            h.old_price,
            h.new_price,
            h.changed_at,
            lead(h.changed_at) OVER (PARTITION BY h.ticket_type_id ORDER BY h.changed_at) AS next_change_at,
            (((h.new_price - h.old_price))::numeric / (NULLIF(h.old_price, 0))::numeric) AS price_pct_change
           FROM catalog.ticket_type_price_history h
          WHERE (h.old_price > 0)
        ), demand_windows AS (
         SELECT pc.ticket_type_id,
            pc.price_pct_change,
            ( SELECT count(*) AS count
                   FROM (orders.order_items oi
                     JOIN orders.orders o ON ((o.id = oi.order_id)))
                  WHERE ((oi.ticket_type_id = pc.ticket_type_id) AND (o.created_at >= (pc.changed_at - '24:00:00'::interval)) AND (o.created_at < pc.changed_at) AND (o.status = ANY (ARRAY['paid'::text, 'paid_partial'::text])))) AS demand_before,
            ( SELECT count(*) AS count
                   FROM (orders.order_items oi
                     JOIN orders.orders o ON ((o.id = oi.order_id)))
                  WHERE ((oi.ticket_type_id = pc.ticket_type_id) AND (o.created_at >= pc.changed_at) AND (o.created_at < COALESCE(pc.next_change_at, (pc.changed_at + '24:00:00'::interval))) AND (o.status = ANY (ARRAY['paid'::text, 'paid_partial'::text])))) AS demand_after,
            pc.changed_at
           FROM price_changes pc
        )
 SELECT ticket_type_id,
    price_pct_change,
    demand_before,
    demand_after,
        CASE
            WHEN ((demand_before > 0) AND (price_pct_change <> (0)::numeric)) THEN ((((demand_after - demand_before))::numeric / (demand_before)::numeric) / price_pct_change)
            ELSE NULL::numeric
        END AS observed_elasticity,
    changed_at
   FROM demand_windows
  WHERE ((demand_before > 0) OR (demand_after > 0));


--
-- Name: VIEW vw_price_elasticity; Type: COMMENT; Schema: catalog; Owner: -
--

COMMENT ON VIEW catalog.vw_price_elasticity IS 'Observed price elasticity per ticket_type. Drives learning loop pro auto-tuning rules.';


--
-- Name: vw_public_price_preview; Type: VIEW; Schema: catalog; Owner: -
--

CREATE VIEW catalog.vw_public_price_preview AS
 SELECT id AS ticket_type_id,
    event_id,
    name AS ticket_type_name,
    base_price AS online_price,
    COALESCE(( SELECT ticket_type_channel_prices.price_override
           FROM catalog.ticket_type_channel_prices
          WHERE ((ticket_type_channel_prices.ticket_type_id = tt.id) AND (ticket_type_channel_prices.channel_key = 'box_office'::text) AND ((ticket_type_channel_prices.effective_from IS NULL) OR (ticket_type_channel_prices.effective_from <= now())) AND ((ticket_type_channel_prices.effective_until IS NULL) OR (ticket_type_channel_prices.effective_until > now())))
         LIMIT 1), base_price) AS box_office_price,
    COALESCE(( SELECT ticket_type_channel_prices.price_override
           FROM catalog.ticket_type_channel_prices
          WHERE ((ticket_type_channel_prices.ticket_type_id = tt.id) AND (ticket_type_channel_prices.channel_key = 'partner'::text) AND ((ticket_type_channel_prices.effective_from IS NULL) OR (ticket_type_channel_prices.effective_from <= now())) AND ((ticket_type_channel_prices.effective_until IS NULL) OR (ticket_type_channel_prices.effective_until > now())))
         LIMIT 1), base_price) AS partner_price,
    remaining_qty,
    visibility
   FROM catalog.ticket_types tt;


--
-- Name: VIEW vw_public_price_preview; Type: COMMENT; Schema: catalog; Owner: -
--

COMMENT ON VIEW catalog.vw_public_price_preview IS 'Public price preview per ticket type × channel. Drives the price calculator.';


--
-- Name: vw_top_picks; Type: VIEW; Schema: catalog; Owner: -
--

CREATE VIEW catalog.vw_top_picks AS
 SELECT e.id AS event_id,
    e.title AS event_title,
    e.date_start,
    tt.id AS ticket_type_id,
    tt.name AS ticket_type_name,
    tt.zone,
    tt.base_price AS min_price_halire,
    tt.remaining_qty,
        CASE
            WHEN (tt.remaining_qty <= 5) THEN 'last_few'::text
            WHEN (tt.remaining_qty <= 20) THEN 'limited'::text
            ELSE 'plenty'::text
        END AS availability,
    (GREATEST(0, (100 - LEAST(tt.remaining_qty, 100))) +
        CASE
            WHEN (tt.base_price < 50000) THEN 30
            WHEN (tt.base_price < 150000) THEN 15
            ELSE 0
        END) AS pick_score
   FROM (catalog.events e
     JOIN catalog.ticket_types tt ON ((tt.event_id = e.id)))
  WHERE ((e.status = 'published'::text) AND (e.date_start > now()) AND (tt.visibility = 'public'::text) AND (tt.remaining_qty > 0))
  ORDER BY (GREATEST(0, (100 - LEAST(tt.remaining_qty, 100))) +
        CASE
            WHEN (tt.base_price < 50000) THEN 30
            WHEN (tt.base_price < 150000) THEN 15
            ELSE 0
        END) DESC;


--
-- Name: VIEW vw_top_picks; Type: COMMENT; Schema: catalog; Owner: -
--

COMMENT ON VIEW catalog.vw_top_picks IS 'TM-style Top Picks per event. Higher pick_score = better deal (low price + available).';


