    CONSTRAINT ad_campaigns_cpc_halire_check CHECK ((cpc_halire >= 100)),
    CONSTRAINT ad_campaigns_slot_check CHECK ((slot = ANY (ARRAY['homepage_hero'::text, 'homepage_featured'::text, 'category_top'::text, 'search_top'::text]))),
    CONSTRAINT ad_campaigns_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text, 'depleted'::text, 'finished'::text])))
);


