COMMENT ON COLUMN marketing.ad_campaigns.status IS 'active=běží, paused=ručně pauznuto, depleted=budget vyčerpaný, finished=ends_at v minulosti.';


--
-- Name: COLUMN ad_campaigns.cross_promo_enabled; Type: COMMENT; Schema: marketing; Owner: -
