    CONSTRAINT campaigns_click_count_check CHECK ((click_count >= 0)),
    CONSTRAINT campaigns_conversion_count_check CHECK ((conversion_count >= 0)),
    CONSTRAINT campaigns_delivered_count_check CHECK ((delivered_count >= 0)),
    CONSTRAINT campaigns_open_count_check CHECK ((open_count >= 0)),
    CONSTRAINT campaigns_recipient_count_check CHECK ((recipient_count >= 0)),
    CONSTRAINT campaigns_revenue_halire_check CHECK ((revenue_halire >= 0)),
    CONSTRAINT campaigns_sent_count_check CHECK ((sent_count >= 0)),
    CONSTRAINT campaigns_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'sending'::text, 'sent'::text, 'paused'::text, 'failed'::text]))),
    CONSTRAINT campaigns_unsubscribe_count_check CHECK ((unsubscribe_count >= 0))
);


