--

COMMENT ON TABLE marketing.promo_code_usages IS 'Auditní log každého použití promo kódu.
   Jeden řádek = jedna objednávka s uplatněným kódem.
   Používá se pro výpočet per-user limitu (max_uses_per_user).
   Cross-schema refs na marketing.promo_codes, orders.orders, identity.users.';


--
-- Name: promo_codes; Type: TABLE; Schema: marketing; Owner: -
--

CREATE TABLE marketing.promo_codes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    code text NOT NULL,
    type text NOT NULL,
    discount_value integer DEFAULT 0 NOT NULL,
    max_uses integer,
    uses_count integer DEFAULT 0 NOT NULL,
    max_uses_per_user integer,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    min_quantity integer DEFAULT 1 NOT NULL,
    min_order_amount integer DEFAULT 0 NOT NULL,
    applicable_ticket_type_ids uuid[],
    applicable_event_ids uuid[],
    stackable boolean DEFAULT false NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_by_organizer_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT promo_codes_discount_value_check CHECK ((discount_value >= 0)),
    CONSTRAINT promo_codes_max_uses_check CHECK (((max_uses IS NULL) OR (max_uses > 0))),
    CONSTRAINT promo_codes_max_uses_per_user_check CHECK (((max_uses_per_user IS NULL) OR (max_uses_per_user > 0))),
    CONSTRAINT promo_codes_min_order_amount_check CHECK ((min_order_amount >= 0)),
    CONSTRAINT promo_codes_min_quantity_check CHECK ((min_quantity >= 1)),
    CONSTRAINT promo_codes_type_check CHECK ((type = ANY (ARRAY['percentage'::text, 'fixed'::text, 'bogo'::text, 'free'::text]))),
    CONSTRAINT promo_codes_uses_count_check CHECK ((uses_count >= 0))
);


--
-- Name: TABLE promo_codes; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON TABLE marketing.promo_codes IS 'Promo kódy pro slevy na vstupenky.
   Typy: percentage (% z celku), fixed (pevná částka v haléřích), bogo (2+1), free (zdarma).
   Atomická inkrementace uses_count zabraňuje race condition při souběžném uplatnění.';


--
-- Name: COLUMN promo_codes.discount_value; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON COLUMN marketing.promo_codes.discount_value IS 'percentage: 0–100 (procent). fixed: haléře. bogo/free: 0 (nepoužito).';


