    campaign_started_at timestamp with time zone DEFAULT now() NOT NULL,
    last_step_sent_at timestamp with time zone,
    current_step integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    churn_score numeric(4,3),
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT re_engagement_campaigns_churn_score_check CHECK (((churn_score >= (0)::numeric) AND (churn_score <= (1)::numeric))),
    CONSTRAINT re_engagement_campaigns_current_step_check CHECK ((current_step >= 0)),
    CONSTRAINT re_engagement_campaigns_dormancy_level_check CHECK ((dormancy_level = ANY (ARRAY['at_risk'::text, 'dormant'::text, 'churned'::text]))),
    CONSTRAINT re_engagement_campaigns_status_check CHECK ((status = ANY (ARRAY['active'::text, 'completed'::text, 'converted'::text, 'unsubscribed'::text])))
);


--
-- Name: TABLE re_engagement_campaigns; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON TABLE marketing.re_engagement_campaigns IS 'Orchestrace re-engagement email/push sérií pro neaktivní uživatele.
   Každý uživatel smí mít max jednu aktivní kampaň (partial unique index).
   CAMPAIGN_STEPS: D+0 email, D+3 push, D+7 email.
   Konverze: první nákup po zahájení kampaně → status = converted.';


--
-- Name: COLUMN re_engagement_campaigns.dormancy_level; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON COLUMN marketing.re_engagement_campaigns.dormancy_level IS 'at_risk (60–89d), dormant (90–179d), churned (180+d).
   Určuje typ zpráv v CAMPAIGN_STEPS.';


--
-- Name: COLUMN re_engagement_campaigns.last_step_sent_at; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON COLUMN marketing.re_engagement_campaigns.last_step_sent_at IS 'Kdy byl odeslán poslední krok. Také se používá pro cooldown kontrolu:
   startCampaign() přeskakuje uživatele, pokud má poslední krok více než 30 dní zpět.';


--
-- Name: COLUMN re_engagement_campaigns.churn_score; Type: COMMENT; Schema: marketing; Owner: -
--

COMMENT ON COLUMN marketing.re_engagement_campaigns.churn_score IS 'Pravděpodobnost odchodu (0.0–1.0) z churn-prediction modulu při spuštění.
   NULL = kampain spuštěna bez ML skóre.';


--
-- Name: re_engagement_unsubscribes; Type: TABLE; Schema: marketing; Owner: -
