--
-- Name: group_invitations; Type: TABLE; Schema: orders; Owner: -
--

CREATE TABLE orders.group_invitations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organizer_user_id uuid NOT NULL,
    event_id uuid NOT NULL,
