--

COMMENT ON TABLE orders.payment_events IS 'Immutable log platebních událostí; záznamy se nesmí mazat (EET retence 10 let).';


--
-- Name: COLUMN payment_events.event_type; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.payment_events.event_type IS 'Typ události (payment_created, payment_paid, payment_refunded, webhook_received, …).';


--
-- Name: COLUMN payment_events.raw_payload; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.payment_events.raw_payload IS 'Kompletní surový JSON payload z GoPay webhook notifikace; nemodifikovaný.';


--
-- Name: COLUMN payment_events.payment_provider; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.payment_events.payment_provider IS 'Provider který vygeneroval tento event. NOT NULL pro audit trail.';


--
-- Name: COLUMN payment_events.stripe_event_id; Type: COMMENT; Schema: orders; Owner: -
--

COMMENT ON COLUMN orders.payment_events.stripe_event_id IS 'Stripe webhook event ID (evt_...). Slouží k idempotency — duplicitní eventy se přeskočí.';


--
-- Name: payment_events_id_seq; Type: SEQUENCE; Schema: orders; Owner: -
--

CREATE SEQUENCE orders.payment_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: payment_events_id_seq; Type: SEQUENCE OWNED BY; Schema: orders; Owner: -
--

ALTER SEQUENCE orders.payment_events_id_seq OWNED BY orders.payment_events.id;


