    CONSTRAINT school_bookings_student_count_check CHECK ((student_count >= 1)),
    CONSTRAINT school_bookings_total_price_halire_check CHECK ((total_price_halire >= 0)),
    CONSTRAINT school_bookings_unit_price_halire_check CHECK ((unit_price_halire >= 0))
);


