    CONSTRAINT api_keys_status_check CHECK ((status = ANY (ARRAY['active'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT api_keys_tier_check CHECK ((tier = ANY (ARRAY['free'::text, 'standard'::text, 'premium'::text])))
);


