-- Name: TABLE api_keys; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON TABLE platform.api_keys IS 'API klíče pro B2B integrátory (POS systémy, partneři, agenti).
   Raw klíč se ukládá pouze při generování — poté jen SHA-256 hash.
   Formát klíče: tick_live_<20 znaků base64url> nebo tick_test_<20 znaků>.';


--
-- Name: COLUMN api_keys.key_prefix; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.api_keys.key_prefix IS 'Prvních 6 znaků náhodné části — zobrazuje se v UI pro identifikaci klíče.
   Příklad: tick_live_Ab3xYz... Nikdy neobsahuje celý klíč.';


--
-- Name: COLUMN api_keys.scopes; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.api_keys.scopes IS 'Pole oprávnění. Dostupné scopes:
   read:events, write:events, write:orders, read:orders,
   read:reports, manage:webhooks, read:tickets, admin:keys.';


