--
-- Name: fee_schedules; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE platform.fee_schedules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    promoter_id uuid NOT NULL,
    name text NOT NULL,
    percentage_fee integer DEFAULT 0 NOT NULL,
    fixed_fee integer DEFAULT 0 NOT NULL,
    min_fee integer,
    max_fee integer,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_until timestamp with time zone,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    buyer_fee_halire integer DEFAULT 0 NOT NULL,
    currency text DEFAULT 'CZK'::text NOT NULL,
    override_reason text,
    buyer_fee_basis text DEFAULT 'per_ticket'::text NOT NULL,
    CONSTRAINT fee_schedules_buyer_fee_basis_check CHECK ((buyer_fee_basis = ANY (ARRAY['per_ticket'::text, 'per_order'::text]))),
    CONSTRAINT fee_schedules_buyer_fee_halire_check CHECK ((buyer_fee_halire >= 0)),
    CONSTRAINT fee_schedules_check CHECK (((min_fee IS NULL) OR (max_fee IS NULL) OR (max_fee >= min_fee))),
    CONSTRAINT fee_schedules_check1 CHECK (((valid_until IS NULL) OR (valid_from <= valid_until))),
    CONSTRAINT fee_schedules_currency_check CHECK ((currency = ANY (ARRAY['CZK'::text, 'EUR'::text]))),
    CONSTRAINT fee_schedules_fixed_fee_check CHECK ((fixed_fee >= 0)),
    CONSTRAINT fee_schedules_max_fee_check CHECK ((max_fee >= 0)),
    CONSTRAINT fee_schedules_min_fee_check CHECK ((min_fee >= 0)),
    CONSTRAINT fee_schedules_percentage_fee_check CHECK (((percentage_fee >= 0) AND (percentage_fee <= 10000)))
);


--
-- Name: TABLE fee_schedules; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON TABLE platform.fee_schedules IS 'Poplatková schémata per promotér. Historické záznamy: is_active=FALSE pro staré schéma.
   Vždy jedno aktivní schéma per promotér (aplikační vrstva to zajistí).';


--
-- Name: COLUMN fee_schedules.percentage_fee; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.fee_schedules.percentage_fee IS 'Procento v basis points: 100 bp = 1 %, 5000 bp = 50 %.';


--
-- Name: COLUMN fee_schedules.max_fee; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.fee_schedules.max_fee IS 'Maximální poplatek (cena za poplatek se limituje). NULL = bez limitu.';


--
-- Name: COLUMN fee_schedules.buyer_fee_halire; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.fee_schedules.buyer_fee_halire IS 'Servisní poplatek pro kupce (per objednávka). Default 0 = pouze procentní fee z promotéra.';


--
-- Name: COLUMN fee_schedules.currency; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.fee_schedules.currency IS 'Měna fee schedule. CZK pro CZ promotéry, EUR pro SR. Lookup matches order currency.';


--
-- Name: COLUMN fee_schedules.override_reason; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.fee_schedules.override_reason IS 'Důvod pro custom sazbu (např. "kulturní dům", "charita", "objem >1M CZK/rok"). Audit trail.';


