--
-- Name: payouts; Type: TABLE; Schema: platform; Owner: -
--

CREATE TABLE platform.payouts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    promoter_id uuid NOT NULL,
    period_from timestamp with time zone NOT NULL,
    period_to timestamp with time zone NOT NULL,
    gross_revenue integer DEFAULT 0 NOT NULL,
    platform_fees integer DEFAULT 0 NOT NULL,
    refunds integer DEFAULT 0 NOT NULL,
    chargebacks integer DEFAULT 0 NOT NULL,
    rolling_reserve integer DEFAULT 0 NOT NULL,
    net_payout integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    payout_cycle text NOT NULL,
    bank_reference text,
    paid_at timestamp with time zone,
    failure_reason text,
    retry_count integer DEFAULT 0 NOT NULL,
    approved_by uuid,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    currency text DEFAULT 'CZK'::text NOT NULL,
    payout_provider text,
    external_payout_id text,
    executed_at timestamp with time zone,
    CONSTRAINT payouts_chargebacks_check CHECK ((chargebacks >= 0)),
    CONSTRAINT payouts_check CHECK ((period_from < period_to)),
    CONSTRAINT payouts_gross_revenue_check CHECK ((gross_revenue >= 0)),
    CONSTRAINT payouts_net_payout_check CHECK ((net_payout >= 0)),
    CONSTRAINT payouts_net_payout_check1 CHECK ((net_payout >= 0)),
    CONSTRAINT payouts_platform_fees_check CHECK ((platform_fees >= 0)),
    CONSTRAINT payouts_refunds_check CHECK ((refunds >= 0)),
    CONSTRAINT payouts_retry_count_check CHECK ((retry_count >= 0)),
    CONSTRAINT payouts_rolling_reserve_check CHECK ((rolling_reserve >= 0)),
    CONSTRAINT payouts_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'paid'::text, 'failed'::text, 'cancelled'::text])))
);


--
-- Name: TABLE payouts; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON TABLE platform.payouts IS 'Immutable výplatní záznamy. Jeden záznam per promotér per období. status=pending → approved → paid/failed.';


--
-- Name: COLUMN payouts.rolling_reserve; Type: COMMENT; Schema: platform; Owner: -
--

COMMENT ON COLUMN platform.payouts.rolling_reserve IS 'Část tržeb zadržená jako rezerva na krytí budoucích chargbacků.';


