    ga4_api_secret_enc text,
    CONSTRAINT chk_brand_color_hex CHECK (((brand_color_hex IS NULL) OR (brand_color_hex ~ '^#[0-9a-fA-F]{6}$'::text))),
    CONSTRAINT promoters_auto_payout_days_after_event_check CHECK ((auto_payout_days_after_event > 0)),
    CONSTRAINT promoters_chargeback_holdback_days_check CHECK (((chargeback_holdback_days IS NULL) OR ((chargeback_holdback_days >= 0) AND (chargeback_holdback_days <= 365)))),
    CONSTRAINT promoters_chargeback_holdback_pct_check CHECK (((chargeback_holdback_pct IS NULL) OR ((chargeback_holdback_pct >= 0) AND (chargeback_holdback_pct <= 2000)))),
    CONSTRAINT promoters_country_check CHECK ((country = ANY (ARRAY['CZ'::text, 'SR'::text]))),
    CONSTRAINT promoters_kyc_status_check CHECK ((kyc_status = ANY (ARRAY['draft'::text, 'submitted'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT promoters_payout_method_check CHECK ((payout_method = ANY (ARRAY['bank_transfer'::text, 'sepa_credit'::text, 'wise'::text]))),
    CONSTRAINT promoters_primary_currency_check CHECK ((primary_currency = ANY (ARRAY['CZK'::text, 'EUR'::text]))),
    CONSTRAINT promoters_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT promoters_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'suspended'::text]))),
    CONSTRAINT promoters_tier_check CHECK (((tier >= 1) AND (tier <= 4))),
    CONSTRAINT promoters_vat_rate_pct_check CHECK (((vat_rate_pct >= 0) AND (vat_rate_pct <= 50)))
);


