--
-- Name: resale_listings; Type: TABLE; Schema: resale; Owner: -
--

CREATE TABLE resale.resale_listings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    seller_id uuid NOT NULL,
    buyer_id uuid,
    ask_price integer NOT NULL,
    original_price integer NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    escrow_status text DEFAULT 'none'::text NOT NULL,
    escrow_gopay_id text,
    listed_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    sold_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    commission_rate integer DEFAULT 0 NOT NULL,
    reserved_until timestamp with time zone,
    payout_amount integer,
    payout_at timestamp with time zone,
    payout_retry_count integer DEFAULT 0 NOT NULL,
    manual_review boolean DEFAULT false NOT NULL,
    mode text DEFAULT 'standard'::text NOT NULL,
    original_purchase_price_halire integer,
    face_value_cap_halire integer,
    barcode_verified_at timestamp with time zone,
    original_ticket_status_snapshot text,
    reissued_ticket_id uuid,
    has_money_back_guarantee boolean DEFAULT true NOT NULL,
    guarantee_label text DEFAULT 'Tixly Guarantee'::text,
    source_label text,
    display_badge text,
    ticket_type_name text,
    seat_label text,
    section_label text,
    platform_fee_halire integer,
    seller_payout_halire integer,
    seller_notes text,
    buyer_order_id uuid,
    CONSTRAINT chk_resale_cancelled_consistency CHECK (((status = 'cancelled'::text) = (cancelled_at IS NOT NULL))),
    CONSTRAINT chk_resale_face_value_enforcement CHECK ((ask_price <= original_price)),
    CONSTRAINT chk_resale_sold_consistency CHECK ((((status = 'sold'::text) AND (buyer_id IS NOT NULL) AND (sold_at IS NOT NULL)) OR ((status = 'reserved'::text) AND (buyer_id IS NOT NULL) AND (sold_at IS NULL)) OR (status <> ALL (ARRAY['sold'::text, 'reserved'::text])))),
    CONSTRAINT listings_ask_price_le_original CHECK ((ask_price <= original_price)),
    CONSTRAINT listings_ask_price_positive CHECK ((ask_price > 0)),
    CONSTRAINT resale_listings_ask_price_check CHECK ((ask_price >= 0)),
    CONSTRAINT resale_listings_commission_rate_check CHECK (((commission_rate >= 0) AND (commission_rate <= 10000))),
    CONSTRAINT resale_listings_escrow_status_check CHECK ((escrow_status = ANY (ARRAY['none'::text, 'held'::text, 'captured'::text, 'released'::text, 'refunded'::text, 'voided'::text]))),
    CONSTRAINT resale_listings_mode_check CHECK ((mode = ANY (ARRAY['standard'::text, 'face_value'::text]))),
    CONSTRAINT resale_listings_original_price_check CHECK ((original_price >= 0)),
    CONSTRAINT resale_listings_payout_amount_check CHECK (((payout_amount IS NULL) OR (payout_amount >= 0))),
    CONSTRAINT resale_listings_payout_retry_count_check CHECK ((payout_retry_count >= 0)),
    CONSTRAINT resale_listings_status_check CHECK ((status = ANY (ARRAY['active'::text, 'reserved'::text, 'sold'::text, 'cancelled'::text, 'expired'::text])))
);


--
-- Name: TABLE resale_listings; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON TABLE resale.resale_listings IS 'Přeprodejní inzeráty; ask_price nesmí překročit original_price (face-value enforcement).';


--
-- Name: COLUMN resale_listings.ask_price; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.ask_price IS 'Požadovaná cena prodejce; CHECK constraint zaručuje ask_price ≤ original_price.';


--
-- Name: COLUMN resale_listings.original_price; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.original_price IS 'Kopie původní ceny z tickets.tickets; denormalizováno pro CHECK constraint bez cross-schema FK.';


--
-- Name: COLUMN resale_listings.status; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.status IS 'active → reserved (kupující klikl) → sold (GoPay captured + TOTP rotováno)
   nebo reserved → active (timeout / void) nebo active → cancelled/expired.';


--
-- Name: COLUMN resale_listings.escrow_status; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.escrow_status IS 'none → held (preauth) → captured (money taken) → released (paid out to seller)
   nebo held → voided (preauth cancelled) nebo captured → refunded (chargeback/dispute).';


--
-- Name: COLUMN resale_listings.escrow_gopay_id; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.escrow_gopay_id IS 'ID escrow platby v GoPay; prostředky jsou zadrženy do potvrzení převodu vstupenky.';


--
-- Name: COLUMN resale_listings.commission_rate; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.commission_rate IS 'Provize platformy v basis points (500 = 5 %). Kopie z platform.fee_schedules při vytvoření listingu.';


--
-- Name: COLUMN resale_listings.reserved_until; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.reserved_until IS 'Platnost rezervace pro kupujícího (status=reserved). Po vypršení se listing vrátí do active.';


--
-- Name: COLUMN resale_listings.payout_amount; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.payout_amount IS 'Čistá výplata prodejci v halířích (ask_price - commission). Nastavena při GoPay capture.';


--
-- Name: COLUMN resale_listings.payout_at; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.payout_at IS 'Kdy byla výplata odeslána prodejci. NULL = čeká na výplatu.';


--
-- Name: COLUMN resale_listings.payout_retry_count; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.payout_retry_count IS 'Počet pokusů o výplatu prodejci. Limit 3 — po překročení přechází na manuální review.';


--
-- Name: COLUMN resale_listings.manual_review; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.manual_review IS 'TRUE = transakce vyžaduje manuální schválení (compliance flag, payout failure > 3×).';


--
-- Name: COLUMN resale_listings.mode; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.mode IS 'standard = seller free price; face_value = fixed at original purchase price (free for seller, TM-style FVE)';


--
-- Name: COLUMN resale_listings.face_value_cap_halire; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.face_value_cap_halire IS 'Max povolená cena pro face_value mode (= original purchase price + fees + tax).';


--
-- Name: COLUMN resale_listings.reissued_ticket_id; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON COLUMN resale.resale_listings.reissued_ticket_id IS 'Při sold: originál tickets.tickets.id se revoke, vznikne nový s novým TOTP secret. Tady link na new.';


