--
-- Name: tickets; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.tickets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    ticket_type_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    original_owner_id uuid NOT NULL,
    seat_id uuid,
    status text DEFAULT 'valid'::text NOT NULL,
    totp_secret_encrypted bytea NOT NULL,
    totp_secret_iv bytea NOT NULL,
    device_binding_id uuid,
    original_price integer NOT NULL,
    transfer_count integer DEFAULT 0 NOT NULL,
    claimed_at timestamp with time zone,
    used_at timestamp with time zone,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    stream_token_hash text,
    stream_first_accessed_at timestamp with time zone,
    stream_access_count integer DEFAULT 0 NOT NULL,
    stream_last_ip_hash text,
    event_seat_id uuid,
    holder_name text,
    scan_count integer DEFAULT 0 NOT NULL,
    currently_inside boolean DEFAULT false NOT NULL,
    last_entry_at timestamp with time zone,
    last_exit_at timestamp with time zone,
    holder_first_name text,
    holder_last_name text,
    bound_phone_e164 text,
    phone_bound_at timestamp with time zone,
    phone_change_requested_at timestamp with time zone,
    phone_change_review_status text,
    reissue_count integer DEFAULT 0 NOT NULL,
    reissue_parent_id uuid,
    reissue_reason text,
    commemorative_sent_at timestamp with time zone,
    transferred_to_user_id uuid,
    transfer_status text,
    CONSTRAINT tickets_original_price_check CHECK ((original_price >= 0)),
    CONSTRAINT tickets_phone_change_review_status_check CHECK ((phone_change_review_status = ANY (ARRAY[NULL::text, 'pending'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT tickets_status_check CHECK ((status = ANY (ARRAY['valid'::text, 'used'::text, 'revoked'::text, 'transferred'::text, 'resale_listed'::text]))),
    CONSTRAINT tickets_transfer_count_check CHECK ((transfer_count >= 0)),
    CONSTRAINT tickets_transfer_status_check CHECK (((transfer_status IS NULL) OR (transfer_status = ANY (ARRAY['pending_transfer'::text, 'transferred'::text]))))
);


--
-- Name: COLUMN tickets.owner_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.owner_id IS 'UUID aktuálního vlastníka vstupenky; aktualizuje se při každém převodu.';


--
-- Name: COLUMN tickets.original_owner_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.original_owner_id IS 'UUID prvního kupujícího; neměnný audit záznam z identity.users.';


--
-- Name: COLUMN tickets.totp_secret_encrypted; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.totp_secret_encrypted IS 'AES-256-GCM šifrovaný TOTP secret pro generování dynamického QR kódu (30s interval).';


--
-- Name: COLUMN tickets.totp_secret_iv; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.totp_secret_iv IS 'Initialization vector (96 bitů) pro AES-256-GCM dešifrování TOTP secretu.';


--
-- Name: COLUMN tickets.device_binding_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.device_binding_id IS 'UUID zařízení z identity.user_devices; pokud nastaveno, vstupenku lze zobrazit pouze na tomto zařízení.';


--
-- Name: COLUMN tickets.original_price; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.original_price IS 'Původní nákupní cena; používá resale service pro enforce face-value pravidla.';


--
-- Name: COLUMN tickets.transfer_count; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.transfer_count IS 'Počet provedených převodů; limit může nastavit organizátor.';


--
-- Name: COLUMN tickets.claimed_at; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.claimed_at IS 'Kdy si vlastník poprvé zobrazil vstupenku (aktivace device binding).';


--
-- Name: COLUMN tickets.stream_token_hash; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.stream_token_hash IS 'SHA-256 hash naposledy vydaného stream tokenu.
   Při vydání nového tokenu se starý implicitně invaliduje (pouze poslední token platí).
   NULL = stream token ještě nebyl vydán.';


--
-- Name: COLUMN tickets.stream_access_count; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.stream_access_count IS 'Počet vydaných stream tokenů (ne přehrání — CDN side).
   Slouží k detekci sdílení přístupu (abuse threshold konfigurovatelný per event).';


--
-- Name: COLUMN tickets.holder_name; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.holder_name IS 'Jméno držitele vstupenky — pokud ticket_type.requires_personalization, vyplněno v checkoutu. Použito v PDF + scanner ID check.';


--
-- Name: COLUMN tickets.scan_count; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.scan_count IS 'Počet entry scanů. Při single-use vždy 0→1. Při reentry až do events.reentry_max_count.';


--
-- Name: COLUMN tickets.currently_inside; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.currently_inside IS 'TRUE = aktuálně uvnitř (entry bez následujícího exit). Slouží pro evakuační listy + reentry rules.';


--
-- Name: COLUMN tickets.bound_phone_e164; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.tickets.bound_phone_e164 IS 'Eventim Pass-style binding. Lístek se zobrazí jen uživateli s tímto číslem. Změna jen přes admin review.';


--
-- Name: vw_ticket_resale_eligibility; Type: VIEW; Schema: resale; Owner: -
--

CREATE VIEW resale.vw_ticket_resale_eligibility AS
 SELECT t.id AS ticket_id,
    t.owner_id,
    t.status AS ticket_status,
    t.original_price,
    tt.resale_allowed,
    tt.is_combo_bundle,
    e.resale_policy,
    e.resale_window_hours_before,
    e.resale_combo_excluded,
    e.date_start AS event_start,
    (e.date_start - ((e.resale_window_hours_before)::double precision * '01:00:00'::interval)) AS resale_deadline,
        CASE
            WHEN (e.resale_policy = 'disabled'::text) THEN 'event_resale_disabled'::text
            WHEN ((e.resale_policy = 'restricted'::text) AND (NOT tt.resale_allowed)) THEN 'ticket_type_not_resellable'::text
            WHEN (e.resale_combo_excluded AND tt.is_combo_bundle) THEN 'combo_excluded'::text
            WHEN (t.status <> 'valid'::text) THEN 'ticket_not_valid'::text
            WHEN (now() > (e.date_start - ((e.resale_window_hours_before)::double precision * '01:00:00'::interval))) THEN 'past_deadline'::text
            ELSE 'eligible'::text
        END AS eligibility_reason,
        CASE
            WHEN (e.resale_policy = 'disabled'::text) THEN false
            WHEN ((e.resale_policy = 'restricted'::text) AND (NOT tt.resale_allowed)) THEN false
            WHEN (e.resale_combo_excluded AND tt.is_combo_bundle) THEN false
            WHEN (t.status <> 'valid'::text) THEN false
            WHEN (now() > (e.date_start - ((e.resale_window_hours_before)::double precision * '01:00:00'::interval))) THEN false
            ELSE true
        END AS is_eligible
   FROM (((tickets.tickets t
     JOIN catalog.ticket_types tt ON ((tt.id = t.ticket_type_id)))
     JOIN orders.orders o ON ((o.id = t.order_id)))
     JOIN catalog.events e ON ((e.id = o.event_id)));


--
-- Name: VIEW vw_ticket_resale_eligibility; Type: COMMENT; Schema: resale; Owner: -
--

COMMENT ON VIEW resale.vw_ticket_resale_eligibility IS 'O(1) resale gate per ticket — vrací is_eligible + machine-readable reason.';


