-- Name: fraud_cases; Type: TABLE; Schema: risk; Owner: -
--

CREATE TABLE risk.fraud_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    user_id uuid NOT NULL,
    promoter_id uuid,
    event_id uuid,
    amount_hellers integer NOT NULL,
    currency character(3) DEFAULT 'CZK'::bpchar NOT NULL,
    risk_score smallint NOT NULL,
    signals jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text DEFAULT 'pending_review'::text NOT NULL,
    priority text DEFAULT 'normal'::text NOT NULL,
    order_held boolean DEFAULT false NOT NULL,
    ip_address inet,
    user_agent text,
    country_code character(2),
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fraud_cases_amount_hellers_check CHECK ((amount_hellers >= 0)),
    CONSTRAINT fraud_cases_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'critical'::text]))),
    CONSTRAINT fraud_cases_risk_score_check CHECK (((risk_score >= 0) AND (risk_score <= 100))),
    CONSTRAINT fraud_cases_status_check CHECK ((status = ANY (ARRAY['pending_review'::text, 'cleared'::text, 'confirmed_fraud'::text, 'escalated'::text])))
);


--
-- Name: TABLE fraud_cases; Type: COMMENT; Schema: risk; Owner: -
--

COMMENT ON TABLE risk.fraud_cases IS 'Fronta podezřelých objednávek pro manuální review adminem.
   Enqueue je volán z checkout pipeline po překročení risk score prahu (≥ 60).';


--
-- Name: COLUMN fraud_cases.signals; Type: COMMENT; Schema: risk; Owner: -
--

COMMENT ON COLUMN risk.fraud_cases.signals IS 'JSONB pole triggerovaných pravidel: [{ rule: string, detail: string, score: number }].
   Každé pravidlo přispívá část k celkovému risk_score.';


--
-- Name: COLUMN fraud_cases.order_held; Type: COMMENT; Schema: risk; Owner: -
--

COMMENT ON COLUMN risk.fraud_cases.order_held IS 'TRUE = objednávka byla automaticky pozastavena; vstupenky nejsou vydány do rozhodnutí.
   Clearing order deblokuje; confirm_fraud spouští cancel.';


--
-- Name: fraud_reviews; Type: TABLE; Schema: risk; Owner: -
--

CREATE TABLE risk.fraud_reviews (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    case_id uuid NOT NULL,
    admin_user_id uuid NOT NULL,
    decision text NOT NULL,
    notes text,
    ban_buyer boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT fraud_reviews_decision_check CHECK ((decision = ANY (ARRAY['clear'::text, 'confirm_fraud'::text, 'escalate'::text, 'add_note'::text])))
);


--
-- Name: TABLE fraud_reviews; Type: COMMENT; Schema: risk; Owner: -
--

COMMENT ON TABLE risk.fraud_reviews IS 'Každý review krok admina. Rozhodnutí ''clear'' a ''confirm_fraud'' jsou terminální.
   ''escalate'' mění prioritu na ''critical'' a přesune case do escalated stavu.
   ''add_note'' jen přidá poznámku bez změny stavu.';


--
-- Name: fraud_rules; Type: TABLE; Schema: risk; Owner: -
--

CREATE TABLE risk.fraud_rules (
    rule_name text NOT NULL,
    description text NOT NULL,
    base_score smallint NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    config jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT fraud_rules_base_score_check CHECK (((base_score >= 0) AND (base_score <= 100)))
);


--
-- Name: TABLE fraud_rules; Type: COMMENT; Schema: risk; Owner: -
--

COMMENT ON TABLE risk.fraud_rules IS 'Konfigurace risk scoring pravidel. base_score = příspěvek pravidla k celkovému risk_score.
   Celkový score = MIN(100, SUM(base_score pro každé triggerované pravidlo)).';


