    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT segments_estimated_size_check CHECK ((estimated_size >= 0))
);


--
-- Name: TABLE segments; Type: COMMENT; Schema: segmentation; Owner: -
--

COMMENT ON TABLE segmentation.segments IS 'Definice audience segmentů pro promotéry. Filter je JSON s podmínkami pro
   dynamický SQL builder (buildWhereClause). Export je omezen na max 50 000 řádků.';


--
-- Name: COLUMN segments.filter; Type: COMMENT; Schema: segmentation; Owner: -
--

COMMENT ON COLUMN segmentation.segments.filter IS 'JSON podmínky segmentu:
   {
     "conditions": [
       { "field": "city", "operator": "eq", "value": "Praha" },
       { "field": "total_orders", "operator": "gte", "value": 3 },
       { "field": "loyalty_tier", "operator": "in", "value": ["gold", "platinum"] }
     ]
   }
   buildWhereClause() převádí na parametrizovaný SQL — žádná string interpolace hodnot.';


--
-- Name: COLUMN segments.estimated_size; Type: COMMENT; Schema: segmentation; Owner: -
--

COMMENT ON COLUMN segmentation.segments.estimated_size IS 'Odhadovaný počet uživatelů v segmentu. Aktualizován při každém volání exportSegment().';


