    sale_end timestamp with time zone,
    capacity integer,
    auto_renewable boolean DEFAULT true NOT NULL,
    renewal_priority_days integer DEFAULT 14 NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    abo_type text DEFAULT 'fixed'::text NOT NULL,
    max_picks_for_choice integer,
    CONSTRAINT packages_abo_type_check CHECK ((abo_type = ANY (ARRAY['fixed'::text, 'choice'::text]))),
    CONSTRAINT packages_base_price_halire_check CHECK ((base_price_halire > 0)),
    CONSTRAINT packages_category_check CHECK ((category = ANY (ARRAY['theater'::text, 'concert_series'::text, 'dance'::text, 'children'::text, 'other'::text]))),
    CONSTRAINT packages_max_picks_check CHECK ((((abo_type = 'fixed'::text) AND (max_picks_for_choice IS NULL)) OR ((abo_type = 'choice'::text) AND (max_picks_for_choice > 0) AND (max_picks_for_choice <= 365)))),
    CONSTRAINT packages_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'on_sale'::text, 'sold_out'::text, 'closed'::text, 'archived'::text])))
);


--
-- Name: TABLE packages; Type: COMMENT; Schema: subscriptions; Owner: -
--

COMMENT ON TABLE subscriptions.packages IS 'Definice balíčku (např. Pondělní abonentka 2026/27)';


--
-- Name: COLUMN packages.abo_type; Type: COMMENT; Schema: subscriptions; Owner: -
--

COMMENT ON COLUMN subscriptions.packages.abo_type IS 'fixed = Festabonnement (auto-issue all events on payment); choice = Wahl-Abo (buyer picks max_picks_for_choice events)';


--
-- Name: COLUMN packages.max_picks_for_choice; Type: COMMENT; Schema: subscriptions; Owner: -
