);


--
-- Name: access_token_log; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.access_token_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    token_id uuid NOT NULL,
    event_type text NOT NULL,
    resource_id uuid NOT NULL,
    reader_device_id text,
    reader_location text,
    auth_method text NOT NULL,
    http_status integer,
    deny_reason text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    budget_decrement bigint,
    budget_after bigint,
    iot_device_id text,
    reading_value numeric,
    reading_unit text,
    CONSTRAINT access_token_log_deny_reason_check CHECK (((deny_reason IS NULL) OR (deny_reason = ANY (ARRAY['expired'::text, 'revoked'::text, 'wrong_resource'::text, 'invalid_totp'::text, 'not_yet_valid'::text, 'rate_limited'::text])))),
    CONSTRAINT chk_access_token_log_auth_method CHECK ((auth_method = ANY (ARRAY['qr_totp'::text, 'nfc_homekey'::text, 'nfc_relay'::text, 'manual_override'::text, 'iot_sensor'::text, 'api_b2b'::text]))),
    CONSTRAINT chk_access_token_log_event_type CHECK ((event_type = ANY (ARRAY['entry'::text, 'exit'::text, 'denied'::text, 'extended'::text, 'revoked'::text, 'replaced'::text, 'budget_decremented'::text, 'budget_exhausted'::text, 'transferred'::text])))
);


--
-- Name: TABLE access_token_log; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.access_token_log IS 'Immutable audit log každého použití access tokenu.
   Každý tap na NFC zámek nebo scan QR čtečkou = 1 záznam.
   Používá se pro bezpečnostní audit, billing (car sharing) a support.';


--
-- Name: access_tokens; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.access_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    booking_id uuid NOT NULL,
    holder_user_id uuid NOT NULL,
    resource_id uuid NOT NULL,
    resource_label text NOT NULL,
    valid_from timestamp with time zone NOT NULL,
    valid_until timestamp with time zone NOT NULL,
    totp_secret_encrypted bytea,
    totp_secret_iv bytea,
    nfc_payload_encrypted bytea,
    nfc_payload_iv bytea,
    status text DEFAULT 'pending'::text NOT NULL,
    extended_until timestamp with time zone,
    extended_at timestamp with time zone,
    extended_by_user_id uuid,
    replaced_by_token_id uuid,
    use_count integer DEFAULT 0 NOT NULL,
    last_used_at timestamp with time zone,
    issued_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    revoked_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resource_type text DEFAULT 'space'::text NOT NULL,
    budget_total bigint,
    budget_remaining bigint,
    budget_unit text,
    issuer_tenant_id uuid,
    verifier_tenant_id uuid,
    transferable boolean DEFAULT true NOT NULL,
    metadata jsonb,
    iot_enabled boolean DEFAULT false NOT NULL,
    iot_device_whitelist text[],
    CONSTRAINT access_tokens_resource_type_check CHECK ((resource_type = ANY (ARRAY['space'::text, 'event'::text, 'dataset'::text, 'license'::text, 'quota'::text, 'permission'::text, 'credential'::text, 'compute'::text, 'service'::text]))),
    CONSTRAINT access_tokens_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'expired'::text, 'revoked'::text, 'extended'::text]))),
    CONSTRAINT chk_access_token_extended CHECK (((extended_until IS NULL) OR (extended_until > valid_until))),
    CONSTRAINT chk_access_token_has_auth CHECK (((totp_secret_encrypted IS NOT NULL) OR (nfc_payload_encrypted IS NOT NULL))),
    CONSTRAINT chk_access_token_nfc_pair CHECK ((((nfc_payload_encrypted IS NULL) AND (nfc_payload_iv IS NULL)) OR ((nfc_payload_encrypted IS NOT NULL) AND (nfc_payload_iv IS NOT NULL)))),
    CONSTRAINT chk_access_token_totp_pair CHECK ((((totp_secret_encrypted IS NULL) AND (totp_secret_iv IS NULL)) OR ((totp_secret_encrypted IS NOT NULL) AND (totp_secret_iv IS NOT NULL)))),
    CONSTRAINT chk_access_token_window CHECK ((valid_until > valid_from)),
    CONSTRAINT chk_access_tokens_totp_iv_pairing CHECK (((totp_secret_encrypted IS NULL) = (totp_secret_iv IS NULL)))
);


--
-- Name: TABLE access_tokens; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.access_tokens IS 'Opakovaný přístup ke zdroji v časovém okně (hotel, coworking, car sharing).
   Token zůstává platný přes N použití, nevyčerpá se (narozdíl od tickets.tickets).
   Jedna objednávka může mít N tokenů — každý host dostane vlastní.
   Verify endpoint musí odpovědět < 100ms (Redis cache).';


--
-- Name: COLUMN access_tokens.resource_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.resource_id IS 'FK na catalog.events — pokoj/kancelář/auto je modelován jako event_type=space_rental.
   resource_label je denormalizovaný label pro zobrazení bez JOIN.';


--
-- Name: COLUMN access_tokens.nfc_payload_encrypted; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.nfc_payload_encrypted IS 'Apple HomeKey: ECDH šifrovaný payload pro NFC Express Mode.
   Vyžaduje Apple HomeKey partner certifikaci.
   NULL pro Fáze 1 (QR-only) a Fáze 2 (NFC relay).';


--
-- Name: COLUMN access_tokens.resource_type; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.resource_type IS 'Sémantický typ tokenu. Řídí business logiku ověření a audit reportování.
   space: hotel, coworking, auto (původní NFC use case).
   license: ČLK licence lékaře, software seat.
   quota: rybářská kvóta, uhlíkový kredit (decrements budget_remaining).
   compute: GPU/QC time slot.
   DEFAULT space zachovává kompatibilitu s existujícími záznamy.';


--
-- Name: COLUMN access_tokens.budget_total; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.budget_total IS 'Celkový rozpočet tokenu v daných jednotkách.
   NULL pro tokeny bez budgetového omezení (use max_uses místo toho).
   Příklady: 50000 (rybářská kvóta 500 kg při budget_unit=''kg''),
             1000000 (grant 10 000 Kč při budget_unit=''czk_halire'').';


--
-- Name: COLUMN access_tokens.budget_remaining; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.budget_remaining IS 'Zbývající nevyčerpaný budget. Atomicky decrementován při každém IoT/scan eventu.
   Stejný atomic decrement vzor jako season_passes.remaining_uses.';


--
-- Name: COLUMN access_tokens.budget_unit; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.budget_unit IS 'Jednotka budgetu. Libovolný string — interpretace záleží na resource_type.
   Doporučené hodnoty: czk_halire, kg, m3, kwh, api_calls, minutes, items.';


--
-- Name: COLUMN access_tokens.issuer_tenant_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.issuer_tenant_id IS 'UUID promotéra/tenanta, který token vydal.
   NULL = vydáno platformou samotnou (platform-level credential).
   Pro profesní licence: UUID tenanta ČLK nebo ČAK.
   Umožňuje cross-tenant verification: nemocnice ověří licenci vydanou ČLK.';


--
-- Name: COLUMN access_tokens.verifier_tenant_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.verifier_tenant_id IS 'UUID tenanta, který smí token ověřovat.
   NULL = kdokoliv s platným API klíčem platformy.
   Pro přísné use cases (zdravotnictví, právo): nastavit na konkrétní tenant.';


--
-- Name: COLUMN access_tokens.transferable; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.transferable IS 'Zda lze token převést na jinou ověřenou identitu (přes resale/transfer API).
   TRUE: hotelový klíč (lze předat kolegovi), softwarová licence (lze přeřadit).
   FALSE: profesní licence (osobní — nepřenositelná), recept (nepřenositelný).';


--
-- Name: COLUMN access_tokens.metadata; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.metadata IS 'Volné JSON pole pro domain-specific atributy.
   Příklady:
   license:    { "specialization": "kardiologie", "issuing_authority": "CLK" }
   quota:      { "species": "kapr", "water_body": "Vltava", "season": "2026" }
   compute:    { "gpu_model": "H100", "memory_gb": 80, "framework": "pytorch" }
   permission: { "drone_type": "DJI Mavic", "max_altitude_m": 120 }
   credential: { "degree": "MUDr.", "university": "UK Praha", "year": 2018 }';


--
-- Name: COLUMN access_tokens.iot_enabled; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.iot_enabled IS 'TRUE = token může být ověřen/dekrementován IoT senzorem (čerpadlo, váha, průtokoměr).
   FALSE = pouze mobilní app nebo B2B API.
   Relevantní pro: vodní práva (průtokoměr), rybářské kvóty (váha na molu),
   EV nabíjení (nabíjecí stanice), GPU cluster (monitoring agent).';


--
-- Name: COLUMN access_tokens.iot_device_whitelist; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.access_tokens.iot_device_whitelist IS 'Whitelist IoT device IDs, které smí dekrementovat budget.
   NULL = jakékoliv registrované IoT zařízení patřící issuer_tenant_id.
   Bezpečnostní prvek — zabraňuje podvodnému decrement z neautorizovaných senzorů.';


--
-- Name: attendee_info; Type: TABLE; Schema: tickets; Owner: -
