--
-- Name: TABLE gift_transfer_log; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.gift_transfer_log IS 'Audit log darování vstupenek (Feature #49). Záznamy se nesmí mazat.
   Propojeno přes transfer_log_id na ticket_transfer_log s old/new TOTP secrets.';


--
-- Name: nfc_taps; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.nfc_taps (
