    CONSTRAINT nfc_taps_result_check CHECK ((result = ANY (ARRAY['admitted'::text, 'expired'::text, 'replay'::text, 'invalid_signature'::text, 'wrong_promoter'::text])))
);


--
-- Name: TABLE nfc_taps; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.nfc_taps IS 'Audit log NFC tap events. Replay protection přes UNIQUE payload_id.';


--
-- Name: pass_updates_log; Type: TABLE; Schema: tickets; Owner: -
