    CONSTRAINT scan_events_scan_type_check CHECK ((scan_type = ANY (ARRAY['entry'::text, 'exit'::text, 'reentry'::text])))
);


--
-- Name: TABLE scan_events; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.scan_events IS 'Time series scan log pro re-entry akce. Pro evakuaci: SELECT WHERE event_id + scan_type=entry AND ticket nemá pozdější exit.';


--
-- Name: scan_logs; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.scan_logs (
    id bigint NOT NULL,
    ticket_id uuid NOT NULL,
    event_id uuid NOT NULL,
    scanned_by_device_id uuid NOT NULL,
    scan_result text NOT NULL,
    scanned_at timestamp with time zone DEFAULT now() NOT NULL,
    override_by uuid,
    override_reason text,
    gate_id uuid,
    denied_reason text,
    CONSTRAINT scan_logs_scan_result_check CHECK ((scan_result = ANY (ARRAY['ok'::text, 'duplicate'::text, 'revoked'::text, 'invalid'::text, 'expired'::text])))
);


--
-- Name: TABLE scan_logs; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.scan_logs IS 'Immutable log skenování vstupenek na vstupní bráně; záznamy se nesmí mazat.';


--
-- Name: COLUMN scan_logs.scanned_by_device_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.scanned_by_device_id IS 'UUID skenovacího zařízení (gate device) z identity.user_devices.';


--
-- Name: COLUMN scan_logs.scan_result; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.scan_result IS 'Výsledek skenování: ok, duplicate (druhý sken), revoked, invalid, expired.';


--
-- Name: COLUMN scan_logs.override_by; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.override_by IS 'UUID personálu, který manuálně přepsal výsledek (např. povolil vstup i přes duplicate).';


--
-- Name: COLUMN scan_logs.override_reason; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.override_reason IS 'Povinný text při override; auditní záznam důvodu přepsání.';


--
-- Name: COLUMN scan_logs.gate_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.gate_id IS 'Fyzická brána (venue_gates) ze které sken přišel — NULL pro web-based scanner bez přiřazené brány';


--
-- Name: COLUMN scan_logs.denied_reason; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.scan_logs.denied_reason IS 'Kód důvodu odepření vstupu (already_used, revoked, wrong_zone_or_day, totp_mismatch, ...)';


--
-- Name: scan_logs_id_seq; Type: SEQUENCE; Schema: tickets; Owner: -
--

CREATE SEQUENCE tickets.scan_logs_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: scan_logs_id_seq; Type: SEQUENCE OWNED BY; Schema: tickets; Owner: -
--

ALTER SEQUENCE tickets.scan_logs_id_seq OWNED BY tickets.scan_logs.id;


--
-- Name: scans; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.scans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    scanned_at timestamp with time zone NOT NULL,
    result text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT scans_result_check CHECK ((result = ANY (ARRAY['valid'::text, 'invalid'::text, 'already_scanned'::text])))
);


--
-- Name: stream_token_log; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.stream_token_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    event_id uuid NOT NULL,
    user_id uuid NOT NULL,
    token_jti text NOT NULL,
    token_issued_at timestamp with time zone DEFAULT now() NOT NULL,
    token_expires_at timestamp with time zone NOT NULL,
    access_type text NOT NULL,
    ip_hash text,
    country_code text,
    geo_blocked boolean DEFAULT false NOT NULL,
    issued boolean DEFAULT true NOT NULL,
    deny_reason text,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT stream_token_log_access_type_check CHECK ((access_type = ANY (ARRAY['live'::text, 'replay'::text]))),
    CONSTRAINT stream_token_log_deny_reason_check CHECK (((deny_reason IS NULL) OR (deny_reason = ANY (ARRAY['geo_blocked'::text, 'ticket_invalid'::text, 'no_stream_access'::text, 'event_not_live'::text, 'replay_expired'::text, 'concurrent_limit'::text]))))
);


--
-- Name: TABLE stream_token_log; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.stream_token_log IS 'Audit log každého pokusu o získání stream tokenu.
   Slouží pro abuse detekci, geo-compliance audit a billing (pay-per-view).
   IP hash uložen bez raw IP — GDPR compliant.';


--
-- Name: ticket_changes; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.ticket_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    change_type text NOT NULL,
    old_ticket_type_id uuid,
    new_ticket_type_id uuid,
    old_event_id uuid,
    new_event_id uuid,
    old_seat_id uuid,
    new_seat_id uuid,
    price_diff_halire integer DEFAULT 0 NOT NULL,
    refund_amount_halire integer DEFAULT 0 NOT NULL,
    initiated_by_user_id uuid,
    initiated_by text NOT NULL,
    reason text,
    status text DEFAULT 'pending'::text NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ticket_changes_change_type_check CHECK ((change_type = ANY (ARRAY['ticket_type'::text, 'event'::text, 'date'::text, 'seat'::text]))),
    CONSTRAINT ticket_changes_initiated_by_check CHECK ((initiated_by = ANY (ARRAY['buyer'::text, 'promoter'::text, 'support'::text]))),
    CONSTRAINT ticket_changes_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'completed'::text, 'rejected'::text, 'cancelled'::text])))
);


--
-- Name: TABLE ticket_changes; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.ticket_changes IS 'Audit log + state machine pro Eventbrite-style ticket swap (typ/event/datum/sedadlo).';


--
-- Name: ticket_modular_access; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.ticket_modular_access (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    event_day_id uuid NOT NULL,
    zone_id uuid NOT NULL,
    access_level text DEFAULT 'general'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT ticket_modular_access_level_check CHECK ((access_level = ANY (ARRAY['general'::text, 'premium'::text, 'vip'::text, 'backstage'::text, 'accessibility'::text])))
);


--
-- Name: TABLE ticket_modular_access; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.ticket_modular_access IS 'Per-ticket selected (day × zone) po koupi modular passu. Scanner validate má fallthrough: pokud řádky existují, validuje proti TĚMTO rows; jinak proti catalog.ticket_type_access (default behavior).';


--
-- Name: ticket_picks; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.ticket_picks (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    event_day_id uuid NOT NULL,
    picked_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: ticket_redemptions; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.ticket_redemptions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    event_day_id uuid NOT NULL,
    zone_id uuid,
    redeemed_at timestamp with time zone DEFAULT now() NOT NULL,
    scanned_by_user_id uuid,
    notes text
);


--
-- Name: ticket_transfer_log; Type: TABLE; Schema: tickets; Owner: -
--

CREATE TABLE tickets.ticket_transfer_log (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    listing_id uuid NOT NULL,
    ticket_id uuid NOT NULL,
    old_totp_secret_encrypted bytea NOT NULL,
    old_totp_secret_iv bytea NOT NULL,
    transferred_at timestamp with time zone DEFAULT now() NOT NULL,
    rolled_back_at timestamp with time zone,
    new_totp_secret_encrypted bytea,
    new_totp_secret_iv bytea,
    reason text,
    actor_user_id uuid,
    CONSTRAINT ticket_transfer_log_reason_check CHECK (((reason IS NULL) OR (reason = ANY (ARRAY['resale_purchase'::text, 'gift_transfer'::text, 'admin_action'::text]))))
);


--
-- Name: TABLE ticket_transfer_log; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON TABLE tickets.ticket_transfer_log IS 'Immutable log TOTP rotací při resale purchaseListing. Záznamy se nesmí mazat.
   Slouží pro rollback při claim timeoutu — pokud kupující neaktivuje vstupenku
   do CLAIM_WINDOW_MS (výchozí 4h), původní secret se obnoví a escrow se voiduje.';


--
-- Name: COLUMN ticket_transfer_log.listing_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.listing_id IS 'UUID resale inzerátu z resale.resale_listings; cross-schema, bez FK.';


--
-- Name: COLUMN ticket_transfer_log.old_totp_secret_encrypted; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.old_totp_secret_encrypted IS 'AES-256-GCM šifrovaný TOTP secret prodejce před rotací. Dešifrovatelný pouze klíčem z TOTP_ENCRYPTION_KEY.';


--
-- Name: COLUMN ticket_transfer_log.transferred_at; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.transferred_at IS 'Kdy byla rotace provedena (začátek claim okna pro kupujícího).';


--
-- Name: COLUMN ticket_transfer_log.rolled_back_at; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.rolled_back_at IS 'NULL = claim pending nebo úspěšně dokončen. NOT NULL = rollback byl proveden (timeout).';


--
-- Name: COLUMN ticket_transfer_log.new_totp_secret_encrypted; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.new_totp_secret_encrypted IS 'AES-256-GCM šifrovaný TOTP secret kupujícího po rotaci. Slouží pro forenzní audit.';


--
-- Name: COLUMN ticket_transfer_log.new_totp_secret_iv; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.new_totp_secret_iv IS 'IV (12B) k new_totp_secret_encrypted.';


--
-- Name: COLUMN ticket_transfer_log.reason; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.reason IS 'Důvod rotace: resale_purchase | gift_transfer | admin_action.';


--
-- Name: COLUMN ticket_transfer_log.actor_user_id; Type: COMMENT; Schema: tickets; Owner: -
--

COMMENT ON COLUMN tickets.ticket_transfer_log.actor_user_id IS 'UUID uživatele, který rotaci vyvolal (buyer při resale, admin při manuální akci).';


--
-- Name: ticket_transfers; Type: TABLE; Schema: tickets; Owner: -
