--
-- Name: configs; Type: TABLE; Schema: verified_fan; Owner: -
--

CREATE TABLE verified_fan.configs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    presale_ticket_type_id uuid NOT NULL,
    presale_price integer NOT NULL,
    slots integer NOT NULL,
    selection_method text DEFAULT 'random'::text NOT NULL,
    registration_opens_at timestamp with time zone NOT NULL,
    registration_closes_at timestamp with time zone NOT NULL,
    selection_at timestamp with time zone NOT NULL,
    link_expires_after_hours integer DEFAULT 48 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_vf_config_dates CHECK ((registration_opens_at < registration_closes_at)),
    CONSTRAINT chk_vf_selection_after_registration CHECK ((selection_at >= registration_closes_at)),
    CONSTRAINT configs_link_expires_after_hours_check CHECK (((link_expires_after_hours > 0) AND (link_expires_after_hours <= 168))),
    CONSTRAINT configs_presale_price_check CHECK ((presale_price >= 0)),
    CONSTRAINT configs_selection_method_check CHECK ((selection_method = ANY (ARRAY['fifo'::text, 'random'::text, 'points'::text]))),
    CONSTRAINT configs_slots_check CHECK ((slots > 0))
);


--
-- Name: TABLE configs; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON TABLE verified_fan.configs IS 'Nastavení Verified Fan programu per event. Jeden záznam per event (UNIQUE event_id).
   selection_method: fifo (první registrovaný), random (náhodný výběr), points (věrnostní body).
   link_expires_after_hours: 1–168 hodin (max 7 dní).';


--
-- Name: COLUMN configs.presale_price; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON COLUMN verified_fan.configs.presale_price IS 'Cena presale vstupenky v halířích. Může být nižší než standard cena — benefit pro vybrané fanoušky.';


--
-- Name: COLUMN configs.slots; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON COLUMN verified_fan.configs.slots IS 'Max počet fanoušků v presale. runSelection() vybere min(slots, registered_count) uživatelů.';


--
-- Name: registrations; Type: TABLE; Schema: verified_fan; Owner: -
--

CREATE TABLE verified_fan.registrations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    user_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    points_at_registration integer DEFAULT 0 NOT NULL,
    access_token text,
    access_token_expires_at timestamp with time zone,
    access_token_used_at timestamp with time zone,
    registered_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT registrations_points_at_registration_check CHECK ((points_at_registration >= 0)),
    CONSTRAINT registrations_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'selected'::text, 'not_selected'::text, 'link_used'::text])))
);


--
-- Name: TABLE registrations; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON TABLE verified_fan.registrations IS 'Registrace fanoušků na Verified Fan presale. UNIQUE (user_id, event_id) — ON CONFLICT DO NOTHING.
   access_token je HS256 JWT uložený v DB pro audit; single-use ochrana přes Redis SETNX.
   Po redemption: status = link_used, access_token_used_at = NOW().';


--
-- Name: COLUMN registrations.points_at_registration; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON COLUMN verified_fan.registrations.points_at_registration IS 'Snapshot věrnostních bodů při registraci (pro selection_method=points).
   Načten z loyalty.accounts.total_points v době registrace.';


--
-- Name: COLUMN registrations.access_token; Type: COMMENT; Schema: verified_fan; Owner: -
--

COMMENT ON COLUMN verified_fan.registrations.access_token IS 'HS256 JWT access token generovaný po selekci. TTL = config.link_expires_after_hours.
   Redis klíč: tixly:vf:token:{tokenHash} — SETNX pro single-use garanci.';


