    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    activated_at timestamp with time zone,
    expires_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT queue_entries_status_check CHECK ((status = ANY (ARRAY['waiting'::text, 'active'::text, 'expired'::text, 'completed'::text])))
);


--
-- Name: queues; Type: TABLE; Schema: waiting_room; Owner: -
--

CREATE TABLE waiting_room.queues (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    event_id uuid NOT NULL,
    promoter_id uuid NOT NULL,
    is_active boolean DEFAULT false NOT NULL,
    max_concurrent_users integer DEFAULT 500 NOT NULL,
    entry_rate_per_min integer DEFAULT 100 NOT NULL,
    session_ttl_seconds integer DEFAULT 600 NOT NULL,
    randomize_entry boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


