--
-- Name: accessible_seats p_accessible_seats_tenant; Type: POLICY; Schema: accessibility; Owner: -
--

CREATE POLICY p_accessible_seats_tenant ON accessibility.accessible_seats USING ((public.app_is_platform_admin() OR (promoter_id = public.app_current_promoter_id()) OR (promoter_id IS NULL)));


--
-- Name: accommodations p_scope; Type: POLICY; Schema: accessibility; Owner: -
--

CREATE POLICY p_scope ON accessibility.accommodations USING ((public.app_is_service() OR public.app_is_platform_admin() OR (EXISTS ( SELECT 1
   FROM (tickets.tickets tk
     JOIN orders.orders o ON ((o.id = tk.order_id)))
  WHERE ((tk.id = accommodations.ticket_id) AND ((o.user_id = public.app_current_user_id()) OR (EXISTS ( SELECT 1
           FROM catalog.events e
          WHERE ((e.id = o.event_id) AND (e.promoter_id = public.app_current_promoter_id()))))))))));


--
-- Name: accessible_seats svc_accessibility_accessible_seats; Type: POLICY; Schema: accessibility; Owner: -
--

CREATE POLICY svc_accessibility_accessible_seats ON accessibility.accessible_seats USING (public.app_is_service()) WITH CHECK (public.app_is_service());


