-- Name: conversions p_rls_conversions; Type: POLICY; Schema: referral; Owner: -
--

CREATE POLICY p_rls_conversions ON referral.conversions USING ((public.app_is_platform_admin() OR public.app_is_service() OR (EXISTS ( SELECT 1
   FROM orders.orders o_
  WHERE ((o_.id = conversions.order_id) AND ((o_.user_id = public.app_current_user_id()) OR (EXISTS ( SELECT 1
           FROM catalog.events ev_
          WHERE ((ev_.id = o_.event_id) AND (ev_.promoter_id = public.app_current_promoter_id()))))))))));


